-- Publish the reviewed photos for six existing menus; preserve catalog and prices.
-- Uploaded privately to menu-products and downloaded with matching SHA-256 before apply.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE six_menu_photo_release (
 id uuid PRIMARY KEY, cafe_id uuid NOT NULL, expected_name text NOT NULL,
 expected_price numeric NOT NULL, previous_path text NOT NULL, next_path text NOT NULL
) ON COMMIT DROP;
DO $guard$
BEGIN
 IF (SELECT count(*) FROM six_menu_photo_release) <> 122 OR (SELECT count(DISTINCT cafe_id) FROM six_menu_photo_release) <> 6 THEN
  RAISE EXCEPTION 'Unexpected six-menu photo release scope';
 END IF;
 PERFORM p.id FROM public.menu_products p JOIN six_menu_photo_release r ON p.id=r.id AND p.cafe_id=r.cafe_id FOR UPDATE OF p;
 IF EXISTS (
  SELECT 1 FROM six_menu_photo_release r LEFT JOIN public.menu_products p ON p.id=r.id AND p.cafe_id=r.cafe_id
  WHERE p.id IS NULL OR p.deleted_at IS NOT NULL OR p.name IS DISTINCT FROM r.expected_name
    OR p.price IS DISTINCT FROM r.expected_price
    OR (p.image_storage_path IS DISTINCT FROM r.previous_path AND p.image_storage_path IS DISTINCT FROM r.next_path)
 ) THEN RAISE EXCEPTION 'Menu changed since photo review; refusing to overwrite'; END IF;
 IF EXISTS (SELECT 1 FROM six_menu_photo_release r WHERE NOT EXISTS (
  SELECT 1 FROM storage.objects o WHERE o.bucket_id='menu-products' AND o.name=r.next_path
 )) THEN RAISE EXCEPTION 'Verified menu uploads are missing'; END IF;
END;
$guard$;
UPDATE public.menu_products p SET image_storage_path=r.next_path
FROM six_menu_photo_release r
WHERE p.id=r.id AND p.cafe_id=r.cafe_id AND p.image_storage_path=r.previous_path;
DO $verify$
BEGIN
 IF (SELECT count(*) FROM public.menu_products p JOIN six_menu_photo_release r
     ON p.id=r.id AND p.cafe_id=r.cafe_id AND p.image_storage_path=r.next_path
     AND p.name=r.expected_name AND p.price=r.expected_price AND p.deleted_at IS NULL) <> 122 THEN
  RAISE EXCEPTION 'Six-menu photo release readback failed';
 END IF;
END;
$verify$;
COMMIT;
